export const passSetRomTraceWatch = (addrs: number[], ranges: number[] = []) => {
  doPostMessage(MSG_MAIN.ROM_TRACE_REQUEST, {
    enable: true,
    watch: addrs.slice(0, 8),
    watchRange: ranges.slice(0, 16),
  })
}

