let didThrowConsoleWarning = false
export let lastIwmReadStats: unknown = null
export const getLastIwmReadStats = () => lastIwmReadStats
export let lastRomTrace: unknown = null
export const getLastRomTrace = () => lastRomTrace
export let lastEnsoniqDocStats: unknown = null
export const getLastEnsoniqDocStats = () => lastEnsoniqDocStats


export const doOnMessage = (e: MessageEvent): {speed: number, helptext: string} | null => {
  switch (e.data.msg as MSG_WORKER) {
    case MSG_WORKER.MACHINE_STATE: {
      const newState = e.data.payload as MachineState
      if (machineState.runMode !== newState.runMode) {
        emulatorSoundEnable(newState.runMode === RUN_MODE.RUNNING)
      }
      let execution = newState.execution
      if (execution) {
        if (resetExecutionSequence) {
          executionSequenceOffset = lastExecutionSequence + 1 - execution.executionSequence
          resetExecutionSequence = false
        }
        execution = {
          ...execution,
          executionSequence: execution.executionSequence + executionSequenceOffset,
        }
      }
      machineState = {...newState, execution}
      if (execution && execution.executionSequence > lastExecutionSequence) {
        lastExecutionSequence = execution.executionSequence
        executionStateCallback?.(execution)
      }
      return {speed: machineState.cpuSpeed, helptext: ""}
    }
    case MSG_WORKER.OPERATION_RESULT:
      resolveWorkerOperation(e.data.payload as WorkerOperationResult)
      break
    case MSG_WORKER.SAVE_STATE: {
      const sState = e.data.payload as EmulatorSaveState
      saveStateCallback?.(sState)
      saveStateCallback = null
      break
    }
    case MSG_WORKER.SAVE_STATE_LOCAL_STORAGE: {
      const sState = e.data.payload as EmulatorSaveState
      if (!sState?.state6502) {
        if (!didThrowConsoleWarning) {
          console.warn("Unable to save large disk images to local storage. Skipping...")
          didThrowConsoleWarning = true
        }
        break
      }
      saveStateLocalStorageCallback?.(sState)
      saveStateLocalStorageCallback = null
      break
    }
    case MSG_WORKER.CLICK:
      clickSpeaker(e.data.payload as number)
      break
    case MSG_WORKER.DRIVE_PROPS: {
      const payload = e.data.payload as DriveProps | {props: DriveProps, replaceDiskData: boolean}
      if ("props" in payload) {
        doSetUIDriveProps(payload.props, payload.replaceDiskData)
      } else {
        doSetUIDriveProps(payload)
      }
      return {speed: machineState.cpuSpeed, helptext: ""}
    }
    case MSG_WORKER.DRIVE_SOUND: {
      const sound = e.data.payload as DRIVE
      doPlayDriveSound(sound)
      break
    }
    case MSG_WORKER.ENSONIQ_DOC_STATS:
      // ?ensoniqdbg=1: DOC access picture for the current boot attempt. A
      // request/response poll (see passSetEnsoniqDebugEnabled), never a sticky
      // worker flag, because worker modules reload under a live page.
      lastEnsoniqDocStats = e.data.payload
      ;(window as unknown as { __ensoniqDocStats?: unknown }).__ensoniqDocStats = lastEnsoniqDocStats
      break
    case MSG_WORKER.IWM_READ_STATS: {
      // Apple IIgs IWM read-cadence instrumentation (?iwmgaps=1 only). Kept on
      // a plain module variable plus a window handle so a headless-browser run
      // can read it with a single Runtime.evaluate.
      lastIwmReadStats = e.data.payload
      if (typeof window !== "undefined") {
        ;(window as unknown as { __iwmStats?: unknown }).__iwmStats = lastIwmReadStats
      }
      break
    }
    case MSG_WORKER.ROM_TRACE: {
      lastRomTrace = e.data.payload
      if (typeof window !== "undefined") {
        // A raw SHR dump arrives on the same channel as the periodic sample, and
        // the sample replaces window.__romTrace every second. Park the dump on its
        // own key so a caller polling at any later time still finds it.
        const dump = (lastRomTrace as { shrDump?: unknown })?.shrDump
        if (dump) {
          ;(window as unknown as { __shrDumpResult?: unknown }).__shrDumpResult = dump
        }
        // Code windows arrive on the same channel and get erased by the next
        // sample for the same reason the dumps did, so accumulate them on their
        // own key: a caller can then make several requests and read one object.
        const windows = (lastRomTrace as { codeWindows?: Array<{ addr: string, bytes: number[] }> })?.codeWindows
        if (windows) {
          const w = window as unknown as { __shrCodeResult?: Array<{ addr: string, bytes: number[] }> }
          if (!w.__shrCodeResult) w.__shrCodeResult = []
          for (const win of windows) {
            const seen = w.__shrCodeResult.find((e) => e.addr === win.addr)
            if (seen) seen.bytes = win.bytes
            else w.__shrCodeResult.push(win)
          }
        }
        ;(window as unknown as { __romTrace?: unknown }).__romTrace = lastRomTrace
      }
      break
    }
    case MSG_WORKER.ADB_TRACE: {
      if (typeof window !== "undefined") {
        ;(window as unknown as { __adbLog?: unknown }).__adbLog = e.data.payload
      }
      break
    }
    case MSG_WORKER.RUMBLE: {
      const params = e.data.payload as GamePadActuatorEffect
      doRumble(params)
      break
    }
    case MSG_WORKER.HELP_TEXT: {
      const helptext = e.data.payload as string
      return {speed: 0, helptext: helptext}
      break
    }
    case MSG_WORKER.SHOW_APPLE_MOUSE: {
      showAppleMouse = e.data.payload as boolean
      break
    }
    case MSG_WORKER.MBOARD_SOUND: {
      const mboard = e.data.payload as MockingboardSound
      playMockingboard(mboard)
      break
    }
    case MSG_WORKER.VERA_PSG_WRITE: {
      const psgWrite = e.data.payload as VeraPsgWrite
      playVeraPsgWrite(psgWrite)
      break
    }
    case MSG_WORKER.VERA_PSG_BATCH: {
      const psgBatch = e.data.payload as VeraPsgWrite[]
      playVeraPsgBatch(psgBatch)
      break
    }
    case MSG_WORKER.VERA_PCM_WRITE: {
      const pcmWrite = e.data.payload as VeraPcmWrite
      playVeraPcmWrite(pcmWrite)
      break
    }
    case MSG_WORKER.VERA_FM_WRITE: {
      playVeraFmWrite(e.data.payload as VeraFmWrite[])
      break
    }
    case MSG_WORKER.VERA_FM_RESET: {
      playVeraFmReset()
      break
    }
    case MSG_WORKER.ENSONIQ_SOUND: {
      const p = e.data.payload as { samples: Int16Array, sampleRate: number }
      playEnsoniqSamples(p.samples, p.sampleRate)

      break
    }
    case MSG_WORKER.VERA_SD_STATUS: {
      veraSdStatus = e.data.payload as VeraSdStatus
      veraSdStatusListeners.forEach(fn => fn(veraSdStatus))
      break
    }
    case MSG_WORKER.VERA_SD_IMAGE_DATA: {
      const payload = e.data.payload as { data: Uint8Array, name: string, writeSeq?: number } | null
      const resolver = veraSdImageResolvers.shift()
      if (resolver) resolver(payload)
      break
    }
    case MSG_WORKER.COMM_DATA: {
      const commdata = e.data.payload as Uint8Array
      receiveCommData(commdata)
      break
    }
    case MSG_WORKER.MIDI_DATA: {
      const mididata = e.data.payload as Uint8Array
      receiveMidiData(mididata)
      break
    }
    case MSG_WORKER.ENHANCED_MIDI: {
      const midiarg = e.data.payload as number
      setEnhancedMidi(midiarg)
      break
    }
    case MSG_WORKER.REQUEST_THUMBNAIL: {
      copyCanvas((blob) => {
        const reader = new FileReader()
        reader.onloadend = function() {
          passThumbnailImage(reader.result as string)
        }        
        reader.readAsDataURL(blob)
      }, true)
      break
    }
    case MSG_WORKER.SOFTSWITCH_DESCRIPTIONS:
      softSwitchDescriptions = e.data.payload as string[]
      break
    case MSG_WORKER.INSTRUCTIONS: {
      const instructions = e.data.payload as Array<PCodeInstr1>
      set6502Instructions(instructions)
      break
    }
    case MSG_WORKER.GET_MEMORY_RESPONSE:
      // This is a response to a GET_MEMORY_REQUEST. Update the memory dump in the state.
      memoryResource = e.data.payload as Uint8Array<ArrayBuffer>
      break
    case MSG_WORKER.SERIAL_CONFIG_CHANGE: {
      const serialConfig = e.data.payload as SerialConfig
      if (serialConfigCallback) serialConfigCallback(serialConfig)
      break
    }
    case MSG_WORKER.VERA_FRAME: {
      latestVeraFrame = e.data.payload as VeraUiFrame
      break
    }
    case MSG_WORKER.ERRORMSG: {
      const errorMsg = e.data.payload as ErrorMsg
      setDialogMessageContext({
        title: "Error",
        message: errorMsg.message,
        code: ERROR_CODE.ERROR,
        actionCancel: () => {},
        actionConfirm: () => {},
      })
      break
    }
    default:
      console.error("main2worker: unknown msg: " + JSON.stringify(e.data))
      break
  }
  return null
}

