import DisassemblyPanel from "./disassembly/disassemblypanel"
import TimeTravelPanel from "./timetravelpanel"
import State6502Controls from "./state6502controls"
import BreakpointsView from "./breakpoints/breakpointsview"
import MemoryMap from "./memory/memorymap"
import StackDump from "./stackdump"
import { isMinimalTheme } from "../ui_settings"
import { useRef, useState, useEffect } from "react"
import { getPreferenceDebugTabLeftWidth, PREFERENCES_RESET_EVENT, setPreferenceDebugTabLeftWidth } from "../localstorage"
import MemoryDump from "./memory/memorydump"
import HeatMapPanel from "./memory/heatmap_panel"
import TabBase from "../tabbase"
import Tab from "../tab"
import { useTranslation } from "../../i18n/useTranslation"

const DebugTab = (props: { updateDisplay: UpdateDisplay }) => {
  const { t } = useTranslation()

  if (isMinimalTheme()) {
    import("./panels.minimal.css")
  }

  const [leftWidth, setLeftWidth] = useState<number>(getPreferenceDebugTabLeftWidth())
  const [isDragging, setIsDragging] = useState(false)
  const leftColumnRef = useRef<HTMLDivElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const handlePreferencesReset = () => {
      setLeftWidth(getPreferenceDebugTabLeftWidth())
    }
    window.addEventListener(PREFERENCES_RESET_EVENT, handlePreferencesReset)
    return () => window.removeEventListener(PREFERENCES_RESET_EVENT, handlePreferencesReset)
  }, [])

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isDragging || !containerRef.current) return
      
      const containerRect = containerRef.current.getBoundingClientRect()
      let newWidth = e.clientX - containerRect.left
      
      // Set min and max width constraints
      if (newWidth < (containerRect.width - 260)) {
        // Reset to default (auto width) if below minimum threshold
        if (newWidth < 265) {
          newWidth = -1
        }
        setLeftWidth(newWidth)
        setPreferenceDebugTabLeftWidth(newWidth)
      }
    }

    const handleMouseUp = () => {
      setIsDragging(false)
    }

    if (isDragging) {
      document.addEventListener("mousemove", handleMouseMove)
      document.addEventListener("mouseup", handleMouseUp)
    }

    return () => {
      document.removeEventListener("mousemove", handleMouseMove)
      document.removeEventListener("mouseup", handleMouseUp)
    }
  }, [isDragging])

  const handleMouseDown = () => {
    setIsDragging(true)
  }

  const isShort = !isMinimalTheme() && window.innerHeight < 900

  return (
  <div className="flex-row-gap debug-section debug-tab">
    <div className="flex-column-gap">
      <State6502Controls />
      <div className="flex-row" ref={containerRef}>
        <div 
          className="flex-column-gap" 
          ref={leftColumnRef}
          style={{ width: leftWidth > 0 ? `${leftWidth}px` : undefined, flexShrink: 0 }}
        >
          <DisassemblyPanel isShort={isShort} />
          <BreakpointsView updateDisplay={props.updateDisplay} />
        </div>
        <div 
          className="dragbar" 
          onMouseDown={handleMouseDown}
        />
        <div className="flex-column-gap">
          <div className="flex-row-gap round-rect-border" id="tour-debug-info">
            <StackDump />
            <MemoryMap updateDisplay={props.updateDisplay} />
          </div>
          <TabBase>
            <Tab title={t("debug.heatMapTitle")}>{(isActive) => <HeatMapPanel isActive={isActive} updateDisplay={props.updateDisplay}/>}</Tab>
            <Tab title={t("debug.memoryDumpTitle")}>{(isActive) => <MemoryDump isActive={isActive} />}</Tab>
          </TabBase>
          <TimeTravelPanel />
        </div>
      </div>
    </div>
  </div>
  )
}

export default DebugTab
