import { useEffect, useRef, useState } from "react"
import { handleGetHeatMapCPU, handleGetHeatMapCPUMax, handleGetHeatMapGetMem, handleGetHeatMapGetMemMax, handleGetHeatMapSetMem, handleGetHeatMapSetMemMax, handleGetRunMode, handleGetState6502 } from "../../main2worker"
import { RUN_MODE, toHex } from "../../../common/utility"
import HeatMapMagnifier from "./heatmap_magnifier"
import { getHeatMapRGBValues, getViridisColorsRGB } from "../../ui_utilities"
import { PaletteName } from "viridis"
import { HEATMAP_STATE } from "./heatmap_panel"

const BASE_HEATMAP_WIDTH = 256
const BASE_HEATMAP_HEIGHT = 256

// let isMouseDown = false
let heatMapCount = 0
let maxIndex = 0
// s6502.cycleCount the canvas was actually redrawn for. The worker posts
// machine state ~60x/sec regardless of whether new instructions/memory
// accesses happened; skip the expensive per-pixel redraw when nothing has
// changed since the last paint. (execution.executionSequence is NOT this
// signal - it only bumps on running/paused/idle transitions, so it never
// changes while the emulator runs continuously.)
let lastDrawnCycleCount = -1
let lastDrawnColorTable: PaletteName | null = null
// Which HEATMAP_STATE (CPU/GETMEM/SETMEM) the canvas currently reflects, as
// reported by the worker for the data it actually sent. This is deliberately NOT
// props.state: clicking a sub-tab re-renders us immediately, but the new array only
// arrives a round-trip later. Stamping props.state would paint the stale array and
// then skip the repaint when the real data showed up - and while paused, that
// round-trip is the only thing that ever changes.
let lastDrawnHeatMapState: HEATMAP_STATE | null = null

const HeatMapView = (props: { state: HEATMAP_STATE,
  colorTable: PaletteName,
  showMagnifier: boolean,
  setShowMagnifier: (value: boolean) => void }) => {
  const heatMapRef = useRef<HTMLCanvasElement>(null)
  const [heatMapAddress, setHeatMapAddressState] = useState<number>(-1)
  const [heatMapPosition, setHeatMapPosition] = useState<[number, number]>([0, 0])
  const [mouseDown, setMouseDown] = useState(false)
  const [magnifierViewport, setMagnifierViewport] = useState<{
    x: number,
    y: number,
    width: number,
    height: number,
  } | null>(null)

  const doSetHeatMapPosition = (x: number, y: number) => {
    setHeatMapPosition([x, y])
  }

  const handleMouseDown = (event: React.MouseEvent<HTMLCanvasElement>) => {
    if (handleGetRunMode() === RUN_MODE.IDLE) return
    if (!props.showMagnifier) props.setShowMagnifier(true)
    const rect = heatMapRef.current?.getBoundingClientRect()
    const offsetX = rect ? event.clientX - rect.left : 0
    const offsetY = rect ? event.clientY - rect.top : 0
    setHeatMapPosition([offsetX, offsetY])
    setMouseDown(true)
    event.preventDefault()
    // const [addr] = getAddressAtMouse(event)
    // if (addr < 0 || isNaN(addr)) return
  }

  const handleMouseMove = (event: React.MouseEvent<HTMLCanvasElement>) => {
    if (!mouseDown) return
    const rect = heatMapRef.current?.getBoundingClientRect()
    const offsetX = rect ? event.clientX - rect.left : 0
    const offsetY = rect ? event.clientY - rect.top : 0
    setHeatMapPosition([offsetX, offsetY])
  }

  const handleMouseUp = () => {
    setMouseDown(false)
  }

  useEffect(() => {
    if (!mouseDown) return
    const stopDragging = () => setMouseDown(false)
    window.addEventListener("mouseup", stopDragging)
    window.addEventListener("blur", stopDragging)
    return () => {
      window.removeEventListener("mouseup", stopDragging)
      window.removeEventListener("blur", stopDragging)
    }
  }, [mouseDown])

  const closeMagnifier = () => {
    props.setShowMagnifier(false)
    setMagnifierViewport(null)
  }

    // const drawGrid = (rgba: Uint8ClampedArray) => {
    //   for (let i = 0; i < BASE_HEATMAP_WIDTH; i += 16) {
    //     for (let j = 0; j < BASE_HEATMAP_HEIGHT; j++) {
    //       const index = i + j * BASE_HEATMAP_WIDTH
    //       rgba[4 * index] = 0
    //       rgba[4 * index + 1] = 0
    //       rgba[4 * index + 2] = 0
    //       rgba[4 * index + 3] = 255
    //     }
    //   }
    //   for (let j = 0; j < BASE_HEATMAP_HEIGHT; j += 16) {
    //     for (let i = 0; i < BASE_HEATMAP_WIDTH; i++) {
    //       const index = i + j * BASE_HEATMAP_WIDTH
    //       rgba[4 * index] = 0
    //       rgba[4 * index + 1] = 0
    //       rgba[4 * index + 2] = 0
    //       rgba[4 * index + 3] = 255
    //     }
    //   }
    // }

  const getHeatMap = () => {
    switch (props.state) {
      case HEATMAP_STATE.CPU:
        return handleGetHeatMapCPU()
      case HEATMAP_STATE.GETMEM:
        return handleGetHeatMapGetMem()
      case HEATMAP_STATE.SETMEM:
        return handleGetHeatMapSetMem()
      default:
        return []
    }
  }
  const getHeatMapMax = () => {
    switch (props.state) {
      case HEATMAP_STATE.CPU:
        return handleGetHeatMapCPUMax()
      case HEATMAP_STATE.GETMEM:
        return handleGetHeatMapGetMemMax()
      case HEATMAP_STATE.SETMEM:
        return handleGetHeatMapSetMemMax()
      default:
        return { index: -1, value: 0 }
    }
  }

  const updateHeatMap = () => {
    const canvas = heatMapRef.current
    const ctx = canvas?.getContext("2d")
    if (!ctx) return
    const heatMap = getHeatMap()
    const heatMapMax = getHeatMapMax() 

    if (heatMap.length === 0) {
      ctx.clearRect(0, 0, BASE_HEATMAP_WIDTH, BASE_HEATMAP_HEIGHT)
      lastDrawnCycleCount = -1
      lastDrawnColorTable = null
      lastDrawnHeatMapState = null
      return
    }
    // Keep the magnifier's live value readout responsive even while paused
    // (e.g. hovering to inspect a frozen heat map), before the "did
    // anything change" bail-out below.
    if (heatMapAddress >= 0) {
      heatMapCount = heatMap[heatMapAddress]
    }
    const cycleCount = handleGetState6502().cycleCount
    if (cycleCount === lastDrawnCycleCount && props.state === lastDrawnHeatMapState
      && props.colorTable === lastDrawnColorTable) return
    lastDrawnCycleCount = cycleCount
    lastDrawnColorTable = props.colorTable
    lastDrawnHeatMapState = props.state
    ctx.imageSmoothingEnabled = false
    const rgba = new Uint8ClampedArray(4 * BASE_HEATMAP_WIDTH * BASE_HEATMAP_HEIGHT)
    // drawGrid(rgba)
    // The peak value/address is tracked incrementally by the producer
    // (cpu6502.ts / memory.ts) as it writes the heat map, instead of being
    // rescanned across all 65536 entries here on every redraw.
    maxIndex = heatMapMax.index
    const colorTable = getViridisColorsRGB(props.colorTable, 16)
    // const heatMapBottom = 75
    for (let i = 0; i < BASE_HEATMAP_WIDTH * BASE_HEATMAP_HEIGHT; i++) {
      const [r, g, b, a] = getHeatMapRGBValues(heatMap[i], heatMapMax.value, colorTable)
      rgba[4 * i] = r
      rgba[4 * i + 1] = g
      rgba[4 * i + 2] = b
      rgba[4 * i + 3] = a
    }
    ctx.putImageData(new ImageData(rgba as ImageDataArray, BASE_HEATMAP_WIDTH, BASE_HEATMAP_HEIGHT), 0, 0)
  }

  useEffect(() => {
    updateHeatMap()
  })

  const doSetHeatMapAddress = (address: number) => {
    setHeatMapAddressState(address)
  }

  const addressStops = Array.from({ length: 15 }, (_, index) => (index + 1) * 0x1000)
  const rowStops = Array.from({ length: 7 }, (_, index) => (index + 1) * 32)

  return (
  <div className="flex-column">
    <div className="mono-text no-select heatmap-address-row">
      {rowStops.map((row, i) => (
        <span key={row} style={{position: "absolute", left: `${(i + 1) * 32}px`}}>
          {`$${toHex(row, 2)}`}
        </span>
      ))}
    </div>
    <div className="flex-row"
      style={{ position: "relative" }}>
      <div className="mono-text no-select heatmap-address-column">
        {addressStops.map((addr) => (
          <div key={addr} style={{position: "absolute", top: `${(addr / 0x1000) * 16}px`}}>
            {`$${toHex(addr, 4)}-`}
          </div>
        ))}
      </div>
      <div style={{ position: "relative" }}>
        <canvas
          ref={heatMapRef}
          className="heatmap-canvas"
          width={BASE_HEATMAP_WIDTH}
          height={BASE_HEATMAP_HEIGHT}
          onMouseMove={handleMouseMove}
          onMouseDown={handleMouseDown}
          onMouseUp={handleMouseUp}
        />
        {magnifierViewport && props.showMagnifier && <div
          aria-hidden="true"
          style={{
            position: "absolute",
            left: `${magnifierViewport.x + 1}px`,
            top: `${magnifierViewport.y + 1}px`,
            width: `${magnifierViewport.width}px`,
            height: `${magnifierViewport.height}px`,
            boxSizing: "border-box",
            border: "1px solid red",
            pointerEvents: "none",
          }}
        />}
      </div>
    </div>
    {props.showMagnifier && <HeatMapMagnifier
        state={props.state}
        heatCanvas={heatMapRef}
        heatMapCount={heatMapCount}
        maxIndex={maxIndex}
        heatMapAddress={heatMapAddress}
        setHeatMapAddress={doSetHeatMapAddress}
        setMagnifierViewport={setMagnifierViewport}
        heatMapPosition={heatMapPosition}
        setHeatMapPosition={doSetHeatMapPosition}
        closeDialog={closeMagnifier} />}
  </div>
  )
}

export default HeatMapView