const saveDiskToCloud = async (driveIndex: number, provider: CloudProvider) => {
  const drive = handleGetDriveProps(driveIndex)
  const blob = getDiskBlobForSync(drive.diskData, drive.filename, drive.hardDrive)
  const cloudData = await provider.upload(
    drive.filename,
    blob,
  )
  if (!cloudData) return
  if (drive.writableFileHandle) await handleSaveWritableFile(driveIndex)
  passSetDriveProps({
    ...drive,
    cloudData,
    writableFileHandle: null,
    diskHasChanges: false,
  })
}

const syncCloudDisk = async (driveIndex: number) => {
  const drive = handleGetDriveProps(driveIndex)
  if (!drive.cloudData || drive.cloudData.isArchive) return
  const provider = drive.cloudData.providerName === "OneDrive"
    ? new OneDriveCloudDrive()
    : drive.cloudData.providerName === "GoogleDrive"
      ? new GoogleDrive()
      : null
  if (!provider) return
  const targetFilename = drive.cloudData.fileName || drive.filename
  const blob = getDiskBlobForSync(drive.diskData, targetFilename, drive.hardDrive)
  if (!await provider.sync(blob, drive.cloudData)) return
  passSetDriveProps({
    ...drive,
    cloudData: { ...drive.cloudData, fileSize: blob.size },
    diskHasChanges: false,
  })
}

const favoriteItem = (
  driveIndex: number,
  drive: DriveProps,
): RetroControlMetadata => {
  return {
    ...controlFromJson("diskTemplates", "diskDrives.{{driveIndex}}.favorite", {}, { driveIndex }),
    selectable: () => canFavoriteDisk(drive),
    ...toggleBinding({
      enabled: currentContext => Boolean(
        currentContext.diskBookmarks && isDiskFavorite(currentContext.diskBookmarks, drive)
      ),
      setEnabled: (currentContext, enabled) => {
        if (!currentContext.diskBookmarks) return
        setDiskFavorite(
          currentContext.diskBookmarks,
          drive,
          enabled,
          currentContext.getDiskScreenshotUrl?.() ?? getCurrentDiskScreenshotUrl(),
        )
      },
    }),
  }
}

const baseWriteProtectItem = (driveIndex: number, drive: DriveProps): RetroControlMetadata => ({
  ...controlFromJson("diskTemplates", "diskDrives.{{driveIndex}}.writeProtected", {}, { driveIndex }),
  selectable: () => Boolean(drive.filename),
  ...toggleBinding({
    enabled: () => drive.isWriteProtected,
    setEnabled: (context, enabled) => {
      handleSetDiskWriteProtected(driveIndex, enabled)
      context.displayProps.updateDisplay()
    },
  }),
})

const ejectItem = (driveIndex: number): RetroControlMetadata => ({
  ...controlFromJson("diskTemplates", "diskDrives.{{driveIndex}}.eject", {}, { driveIndex }),
  selectable: () => Boolean(handleGetDriveProps(driveIndex).filename),
  action: context => {
    handleEjectDisk(driveIndex)
    context.displayProps.updateDisplay()
  },
})

export const insertedDiskItems = (
  driveIndex: number,
): RetroControlMetadata[] => {
  const drive = handleGetDriveProps(driveIndex)
  const hasDisk = Boolean(drive.filename)
  const isElectron = navigator.userAgent.includes("Electron")
  const activeCloudDisk = Boolean(
    drive.cloudData &&
    drive.cloudData.syncStatus !== CLOUD_SYNC.INACTIVE &&
    !drive.cloudData.isArchive
  )
  const supportedCloudDisk = Boolean(
    activeCloudDisk && (
      drive.cloudData?.providerName === "OneDrive" || drive.cloudData?.providerName === "GoogleDrive"
    )
  )
  const setSyncInterval = (syncInterval: number) => {
    const latestDrive = handleGetDriveProps(driveIndex)
    if (!latestDrive.cloudData) return
    doSetUIDriveProps({
      ...latestDrive,
      cloudData: { ...latestDrive.cloudData, syncInterval },
    })
  }

  const downloadItems: RetroControlMetadata[] = [
    {
      ...controlFromJson("diskTemplates", "diskDrives.{{driveIndex}}.download", {}, { driveIndex }),
      selectable: () => hasDisk,
      action: () => downloadDiskToDevice(driveIndex),
    },
    {
      ...controlFromJson("diskTemplates", "diskDrives.{{driveIndex}}.downloadWoz", {}, { driveIndex }),
      selectable: () => hasDisk && !drive.hardDrive && !drive.filename.toLowerCase().endsWith(".woz"),
      action: () => downloadDiskToDevice(driveIndex, true),
    },
    {
      ...controlFromJson("diskTemplates", "diskDrives.{{driveIndex}}.downloadAndEject", {}, { driveIndex }),
      selectable: () => hasDisk,
      action: (currentContext: RetroMenuContext) => {
        downloadDiskToDevice(driveIndex)
        handleEjectDisk(driveIndex)
        currentContext.displayProps.updateDisplay()
      },
    },
    ejectItem(driveIndex),
  ]

  const saveToItems: RetroControlMetadata[] = [
    {
      ...controlFromJson("diskTemplates", "diskDrives.{{driveIndex}}.saveToOneDrive", {}, { driveIndex }),
      selectable: () => hasDisk && !isElectron,
      action: () => { void saveDiskToCloud(driveIndex, new OneDriveCloudDrive()) },
    },
    {
      ...controlFromJson("diskTemplates", "diskDrives.{{driveIndex}}.saveToGoogleDrive", {}, { driveIndex }),
      selectable: () => hasDisk && !isElectron,
      action: () => { void saveDiskToCloud(driveIndex, new GoogleDrive()) },
    },
  ]

  const saveItems: RetroControlMetadata[] = [
    {
      ...controlFromJson("diskTemplates", "diskDrives.{{driveIndex}}.saveToDevice", {}, { driveIndex }),
      selectable: () => hasDisk && isFileSystemApiSupported() && !drive.writableFileHandle,
      action: () => { void saveDiskToDevice(driveIndex) },
    },
    {
      ...controlFromJson("diskTemplates", "diskDrives.{{driveIndex}}.saveTo", {}, { driveIndex }),
      selectable: () => hasDisk && !isElectron,
      dynamicChildren: () => saveToItems,
    },
    {
      ...controlFromJson("diskTemplates", "diskDrives.{{driveIndex}}.pauseSyncing", {}, { driveIndex }),
      selectable: () => activeCloudDisk,
      indicator: () => drive.cloudData?.syncInterval === Number.MAX_VALUE ? "*" : undefined,
      action: () => setSyncInterval(Number.MAX_VALUE),
    },
    {
      ...controlFromJson("diskTemplates", "diskDrives.{{driveIndex}}.syncNow", {}, { driveIndex }),
      selectable: () => supportedCloudDisk,
      action: () => { void syncCloudDisk(driveIndex) },
    },
  ]

  const favorite = favoriteItem(
    driveIndex,
    drive,
  )

  // Multi-disk swap group — only shown when there are 2 or more valid standby disks
  const standby = getStandbyDisks(driveIndex)
  const validDisks = standby.filter(d => Boolean(d?.filename?.trim()))

  const swapGroup: RetroControlMetadata[] = validDisks.length >= 2 ? diskMenuGroup(
    driveIndex,
    "swapSeparator",
    (context: RetroMenuContext) => context.t("disk.standbyDisks"),
    [
      ...validDisks.map((disk, idx) => {
        const cleanName = getCleanDiskFilename(disk.filename)
        const displayName = disk.comment ? `${cleanName} (${disk.comment})` : cleanName
        return {
          ...controlFromJson(
            "diskTemplates",
            "diskDrives.{{driveIndex}}.swapDisk.{{diskIndex}}",
            diskTemplateBindings,
            { driveIndex, diskIndex: idx },
          ),
          label: displayName,
          indicator: () => idx === getStandbyActiveIndex(driveIndex) ? "*" : undefined,
          selectable: () => true,
          refreshAfterAction: true,
          action: async (ctx?: RetroMenuContext) => {
            if (idx !== getStandbyActiveIndex(driveIndex)) {
              const curDrive = handleGetDriveProps(driveIndex)
              if (curDrive.diskHasChanges && curDrive.writableFileHandle) {
                await handleSaveWritableFile(driveIndex)
              }
              await swapStandbyDisk(driveIndex, idx, undefined, () => ctx?.displayProps?.updateDisplay?.())
            }
          },
        }
      }),
      {
        ...controlFromJson(
          "diskTemplates",
          "diskDrives.{{driveIndex}}.ejectAll",
          {},
          { driveIndex },
        ),
        selectable: () => true,
        action: (ctx: RetroMenuContext) => {
          ejectAllDisks(driveIndex, () => ctx.displayProps.updateDisplay())
        },
      },
    ],
  ) : []

  return [
    ...swapGroup,
    ...diskMenuGroup(driveIndex, "diskSeparator", "Disk", [
      baseWriteProtectItem(driveIndex, drive),
      favorite,
    ]),
    ...diskMenuGroup(driveIndex, "downloadSeparator", "Download", downloadItems),
    ...diskMenuGroup(driveIndex, "saveSeparator", "Save", saveItems),
  ]
}

const diskDrives = [
  { index: 0, slot: 7 },
  { index: 1, slot: 7 },
  { index: 2, slot: 6 },
  { index: 3, slot: 6 },
  // Apple IIgs only: the built-in 3.5" drive pair in slot 5.
  { index: 4, slot: 5 },
  { index: 5, slot: 5 },
] as const

const diskBindings: RetroControlBindings = {
  ...Object.fromEntries(collectionTabs.map(tab => [
    tab.id,
    {
      submenuTitleValue: tab.index === TAB_INDEX.EXPORT
        ? (_runtime: RetroMenuContext, items: readonly RetroResolvedControl[] = [], values: number[] = []) =>
          getRetroExportHdvSize(items, values)
        : undefined,
      dynamicChildren: (runtime: RetroMenuContext, items?: readonly RetroResolvedControl[], values?: number[]) => {
        const disks = (tab.index === TAB_INDEX.FAVORITES || tab.index === TAB_INDEX.EXPORT
          ? getCollection()
          : runtime.diskCollection ?? getCollection()).filter(tab.filter)
        if (tab.index !== TAB_INDEX.EXPORT && items === undefined && values === undefined) {
          resetCollectionDriveTab(tab.index)
        }
        return tab.index === TAB_INDEX.EXPORT
          ? createRetroExportScreenItems(runtime, disks, items, values)
          : collectionItems(runtime, tab.index, disks, getDiskCollectionSortMode(tab.index), items, values)
      },
      actionLabel: (runtime: RetroMenuContext) => runtime.t(tab.index === TAB_INDEX.EXPORT ? "collection.export" : "retroControl.load"),
      submit: tab.index === TAB_INDEX.EXPORT
        ? (runtime: RetroMenuContext, items: readonly RetroResolvedControl[], values: number[]) => {
          const selectedDisks = items
            .filter((item, index) => values[index] === 1 && item.payload)
            .map(item => item.payload as DiskCollectionItem)
          void exportDisks(runtime, selectedDisks)
        }
        : undefined,
      onLeave: tab.index === TAB_INDEX.FAVORITES
        ? (runtime: RetroMenuContext, items: readonly RetroResolvedControl[], values: number[]) => {
          items.forEach((item, index) => {
            const bookmarkId = (item.payload as DiskCollectionItem | undefined)?.bookmarkId
            if (bookmarkId && values[index] === item.checkmarkIndex) {
              runtime.diskBookmarks?.remove(bookmarkId)
            }
          })
        }
        : undefined,
      isSubmitVisible: tab.index === TAB_INDEX.EXPORT
        ? (_runtime: RetroMenuContext, items: readonly RetroResolvedControl[], values: number[]) => {
          const selectedDiskKeys = selectedExportDiskKeys(items, values)
          const disks = items.flatMap(item => item.payload ? [item.payload as DiskCollectionItem] : [])
          return selectedDiskKeys.size > 0 && getCloudProvidersNeedingAuth(
            exportNotificationDisks(disks, selectedDiskKeys)
              .filter(disk => disk.type === DISK_COLLECTION_ITEM_TYPE.CLOUD_DRIVE),
          ).length === 0
        }
        : undefined,
    } satisfies Partial<RetroControlMetadata>,
  ])),
  "diskDrives.none": {
    isVisible: () => diskDrives.every(({ slot }) => handleGetSlotConfig()[slot] === "none")
      && handleGetSlotConfig()[2] !== "vera" && handleGetSlotConfig()[4] !== "vera",
  },
  "diskDrives.vera": {
    label: (context: RetroMenuContext) => {
      const cfg = handleGetSlotConfig()
      const slot = cfg[2] === "vera" ? 2 : (cfg[4] === "vera" ? 4 : 2)
      const status = handleGetVeraSdStatus()
      return context.t("retroControl.drive", {
        drive: `S${slot},SD`,
        disk: status.attached
          ? `${status.hasChanges ? "*" : ""}${decodeDiskTitle(status.name)}`
          : context.t("retroControl.card.empty"),
      })
    },
    isVisible: () => {
      const cfg = handleGetSlotConfig()
      return cfg[2] === "vera" || cfg[4] === "vera"
    },
    dynamicChildren: () => veraSdRetroItems(),
    actionLabel: (context: RetroMenuContext) => context.t(handleGetVeraSdStatus().attached
      ? "retroControl.select"
      : "retroControl.load"),
    contextualActionLabel: (context: RetroMenuContext) => handleGetVeraSdStatus().attached
      ? context.t("retroControl.options")
      : context.t("retroControl.load"),
  },
  ...Object.fromEntries(diskDrives.map(({ index, slot }) => [
    `diskDrives.${index}`,
    {
      label: (context: RetroMenuContext) => {
        const drive = handleGetDriveProps(index)
        const filename = handleGetFilename(index)
        return context.t("retroControl.drive", {
          drive: DISK_DRIVE_LABELS[index],
          disk: filename
            ? `${drive.diskHasChanges ? "*" : ""}${decodeDiskTitle(filename)}`
            : context.t("retroControl.card.empty"),
        })
      },
      isVisible: () => handleGetSlotConfig()[slot] !== "none",
      dynamicChildren: () => [
        ...diskLoadItems(index),
        ...insertedDiskItems(index),
      ],
      actionLabel: (context: RetroMenuContext) => context.t(handleGetDriveProps(index).filename
        ? "retroControl.select"
        : "retroControl.load"),
      contextualActionLabel: (context: RetroMenuContext) => handleGetDriveProps(index).filename
        ? context.t("retroControl.options")
        : context.t("retroControl.load"),
    } satisfies Partial<RetroControlMetadata>,
  ])),
}

export const retroDiskControls: RetroControlMetadata[] = controlsFromJson("disk", diskBindings)

const DiskInterface = (props: DisplayProps) => {
  const { t } = useTranslation()
  const [isFlyoutOpen, setIsFlyoutOpen] = useState(false)
  const height = window.innerHeight ? window.innerHeight : (window.outerHeight - 120)
  const width = window.innerWidth ? window.innerWidth : (window.outerWidth - 20)
  const isScreenNarrow = width < height

  const [slotConfig, setSlotConfig] = useState(handleGetSlotConfig)
  useEffect(() => {
    const handleSlotChange = () => setSlotConfig({ ...handleGetSlotConfig() })
    window.addEventListener("apple2ts-slot-config-changed", handleSlotChange)
    return () => window.removeEventListener("apple2ts-slot-config-changed", handleSlotChange)
  }, [])

  const isVeraInstalled = slotConfig[2] === "vera" || slotConfig[4] === "vera"
  // The Apple IIgs has a second built-in floppy slot (slot 5, 3.5") alongside
  // slot 6 (5.25"). Drives 4 and 5 only exist on that machine.
  const isIIgs = handleGetMachineName() === "APPLE2GS"
  const allSlotsDisabled = slotConfig[1] === "none" && slotConfig[6] === "none" && slotConfig[7] === "none" && !isVeraInstalled

  return (
    <span style={{ opacity: allSlotsDisabled ? 0.4 : 1, filter: allSlotsDisabled ? "grayscale(100%)" : "none", pointerEvents: allSlotsDisabled ? "none" : "auto", cursor: allSlotsDisabled ? "not-allowed" : "pointer" }}>
      <Flyout
        icon={faHdd}
        title={t("disk.diskDrivesAndDevices")}
        isOpen={() => { return isFlyoutOpen && !allSlotsDisabled }}
        onClick={() => { if (!allSlotsDisabled) setIsFlyoutOpen(!isFlyoutOpen) }}
        shift={true}
        position="top-left">
        <div className={`${isMinimalTheme() && isScreenNarrow ? "flex-column" : "flex-row"} flexwrap`}>
          <span className="flex-row">
            {!isMinimalTheme() && <DiskImageChooser {...props} />}
            <DiskDrive key={0} index={0} renderCount={props.renderCount}
              setShowFileOpenDialog={props.setShowFileOpenDialog} updateDisplay={props.updateDisplay} />
            <DiskDrive key={1} index={1} renderCount={props.renderCount}
              setShowFileOpenDialog={props.setShowFileOpenDialog} updateDisplay={props.updateDisplay} />
            {(isMinimalTheme() && isScreenNarrow) && <VeraSdIcon renderCount={props.renderCount} />}
            {(isMinimalTheme() && isScreenNarrow) && <ImageWriter />}
          </span>
          <span className="flex-row">
            <DiskDrive key={2} index={2} renderCount={props.renderCount}
              setShowFileOpenDialog={props.setShowFileOpenDialog} updateDisplay={props.updateDisplay} />
            <DiskDrive key={3} index={3} renderCount={props.renderCount}
              setShowFileOpenDialog={props.setShowFileOpenDialog} updateDisplay={props.updateDisplay} />
            {isIIgs && <DiskDrive key={4} index={4} renderCount={props.renderCount}
              setShowFileOpenDialog={props.setShowFileOpenDialog} updateDisplay={props.updateDisplay} />}
            {isIIgs && <DiskDrive key={5} index={5} renderCount={props.renderCount}
              setShowFileOpenDialog={props.setShowFileOpenDialog} updateDisplay={props.updateDisplay} />}
            {(!isMinimalTheme() || !isScreenNarrow) && <VeraSdIcon renderCount={props.renderCount} />}
            {(!isMinimalTheme() || !isScreenNarrow) && <ImageWriter />}
          </span>
        </div>
      </Flyout>
    </span>
  )
}

export default DiskInterface