import { gunzipSync } from "fflate"
import {
  QR_HGR_PATCHES_ADDRESS,
  QR_HGR_PATCHES_BYTES,
  QR_HGR_RENDERER_ADDRESS,
  QR_HGR_RENDERER_BYTES,
  QR_HGR_SHIMS_ADDRESS,
  QR_HGR_SHIMS_BYTES,
  QR_HGR_TRAMPOLINE_ADDRESS,
  QR_HGR_TRAMPOLINE_BYTES,
} from "./qr_hgr_assembly.generated"

// Extracted from QR.BIN in qrdemo.po at badvision/apple2-qr-hgr commit
// fba734057ae8cb08d11445f4cacdce83260feeb3.
// SHA-256: 086048c29832a929350393d729be58dc966bc842b469b6177cc63a01da110d0a
const QR_HGR_GZIP_BASE64 =
  ""

const QR_HGR_BINARY_LENGTH = 3787
const QR_HGR_LOAD_ADDRESS = 0x6000

export const createQrHgrRuntimeBinary = (): Uint8Array => {
  const compressed = Uint8Array.from(atob(QR_HGR_GZIP_BASE64), character => character.charCodeAt(0))
  const qrBinary = gunzipSync(compressed)
  if (qrBinary.length !== QR_HGR_BINARY_LENGTH) {
    throw new Error(`Unexpected QR.BIN length: ${qrBinary.length}`)
  }
  qrBinary.set(QR_HGR_PATCHES_BYTES, QR_HGR_PATCHES_ADDRESS - QR_HGR_LOAD_ADDRESS)

  const runtime = new Uint8Array(
    QR_HGR_RENDERER_ADDRESS - QR_HGR_LOAD_ADDRESS + QR_HGR_RENDERER_BYTES.length,
  )
  runtime.set(qrBinary)
  runtime.set(QR_HGR_SHIMS_BYTES, QR_HGR_SHIMS_ADDRESS - QR_HGR_LOAD_ADDRESS)
  runtime.set(QR_HGR_TRAMPOLINE_BYTES, QR_HGR_TRAMPOLINE_ADDRESS - QR_HGR_LOAD_ADDRESS)
  runtime.set(QR_HGR_RENDERER_BYTES, QR_HGR_RENDERER_ADDRESS - QR_HGR_LOAD_ADDRESS)
  return runtime
}

export const createQrHgrScaledPixelBinary = (): Uint8Array => QR_HGR_RENDERER_BYTES.slice()